import { formatEuros } from './money.js';
import { getCustomer } from './customers.js';
import { lineTotal, lineDiscount, invoiceTotals } from './invoices.js';
import { balanceDue } from './payments.js';

/**
 * Render an invoice as plain text.
 * @param {{ number?: string, customerId: string, lines: Array<{ qty: number, name: string, unitPrice: number, discountPercent?: number }>, dueDate?: string, payments?: Array, voucher?: { code: string, amount: number } }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const numberLine = invoice.number || 'DRAFT';

  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : 'Unknown Customer';

  const lineItems = invoice.lines
    .map((line) => {
      const total = lineTotal(line);
      const discount = lineDiscount(line);
      let lineStr = `${line.qty} x ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(total)}`;
      if (discount > 0) {
        lineStr += `\n  Discount: ${formatEuros(discount)}`;
      }
      return lineStr;
    })
    .join('\n');

  const totals = invoiceTotals(invoice);
  const sections = [numberLine, customerName, lineItems];

  if (totals.voucher > 0) {
    const voucherCode = invoice.voucher?.code || 'VOUCHER';
    sections.push(`Voucher (${voucherCode}): ${formatEuros(totals.voucher)}`);
  }

  sections.push(`VAT: ${formatEuros(totals.vat)}`);
  sections.push(`Total: ${formatEuros(totals.total)}`);

  if (invoice.dueDate) {
    sections.push(`Due: ${invoice.dueDate}`);
  }

  if (invoice.payments && invoice.payments.length > 0) {
    const paid = invoice.payments.reduce((sum, p) => sum + p.amount, 0);
    sections.push(`Paid: ${formatEuros(paid)}`);
  }

  return sections.join('\n');
}

