import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice, issueInvoice, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('renderInvoiceText shows DRAFT for a draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  const text = renderInvoiceText(r.value);

  assert.ok(text.startsWith('DRAFT'));
});

test('renderInvoiceText shows the invoice number for an issued invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  const r2 = issueInvoice(r1.value, []);
  const text = renderInvoiceText(r2.value);

  assert.ok(text.startsWith('INV-2026-0001'));
});

test('renderInvoiceText shows the customer name', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');

  assert.equal(lines[1], 'Northwind Studio');
});

test('renderInvoiceText shows line items with qty, name, unit price and total', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');

  assert.equal(lines[2], '10 x Development (hour) @ €95.00 = €950.00');
});

test('renderInvoiceText formats amounts as euros', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 2 }],
  });

  const text = renderInvoiceText(r.value);

  assert.ok(text.includes('€1,200.00'));
  assert.ok(text.includes('€2,400.00'));
});

test('renderInvoiceText shows multiple line items', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 9, discountPercent: 0 },
      { sku: 'DES-HOUR', qty: 5, discountPercent: 0 },
    ],
  });

  const text = renderInvoiceText(r.value);

  assert.ok(text.includes('9 x Development (hour) @ €95.00 = €855.00'));
  assert.ok(text.includes('5 x Design work (hour) @ €85.00 = €425.00'));
});

test('renderInvoiceText shows the correct total', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 9, discountPercent: 0 },
      { sku: 'DES-HOUR', qty: 5, discountPercent: 0 },
    ],
  });

  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');

  assert.ok(lines.some((l) => l.startsWith('VAT:')));
  assert.ok(lines.some((l) => l.startsWith('Total:')));
  assert.ok(text.includes('Total: €1,481.36'));
});

test('renderInvoiceText works with a single line item', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'BRAND-BOOK', qty: 1, discountPercent: 0 }],
  });

  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');

  assert.equal(lines.length, 5);
  assert.ok(lines[0].startsWith('DRAFT'));
  assert.equal(lines[1], 'Kite & Co');
  assert.equal(lines[2], '1 x Brand guidelines document @ €2,450.00 = €2,450.00');
  assert.ok(lines[3].startsWith('VAT:'));
  assert.ok(lines[4].startsWith('Total:'));
});

test('renderInvoiceText shows Unknown Customer if customer not found', () => {
  const fakeInvoice = {
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ qty: 1, name: 'Test', unitPrice: 1000 }],
  };

  const text = renderInvoiceText(fakeInvoice);
  const lines = text.split('\n');

  assert.equal(lines[1], 'Unknown Customer');
});

test('renderInvoiceText formats a complete issued invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 8, discountPercent: 0 },
      { sku: 'DES-HOUR', qty: 3, discountPercent: 0 },
    ],
  });

  const r2 = issueInvoice(r1.value, ['INV-2026-0001']);

  const text = renderInvoiceText(r2.value);
  const lines = text.split('\n');

  assert.equal(lines[0], 'INV-2026-0002');
  assert.equal(lines[1], 'Northwind Studio');
  assert.equal(lines[2], '8 x Development (hour) @ €95.00 = €760.00');
  assert.equal(lines[3], '3 x Design work (hour) @ €85.00 = €255.00');
  assert.ok(lines[4].startsWith('VAT:'));
  assert.ok(lines[5].startsWith('Total:'));
});

test('renderInvoiceText handles three line items', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'COPY-HOUR', qty: 3 },
    ],
  });

  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');

  assert.equal(lines.length, 7);
  assert.equal(lines[2], '5 x Development (hour) @ €95.00 = €475.00');
  assert.equal(lines[3], '2 x Design work (hour) @ €85.00 = €170.00');
  assert.equal(lines[4], '3 x Copywriting (hour) @ €60.00 = €180.00');
  assert.ok(lines[5].startsWith('VAT:'));
  assert.ok(lines[6].startsWith('Total:'));
});

test('renderInvoiceText shows line discount when present', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 9, discountPercent: 10 }],
  });

  const text = renderInvoiceText(r.value);

  assert.ok(text.includes('Discount: €95.00'));
});

test('renderInvoiceText does not show line discount when zero', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 9, discountPercent: 0 }],
  });

  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');

  for (const line of lines) {
    assert.ok(!line.includes('Discount:'));
  }
});

test('renderInvoiceText shows voucher before total', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 9, discountPercent: 0 }],
  });

  const r2 = applyVoucher(r1.value, { code: 'SAVE10', amount: 10000 });
  const text = renderInvoiceText(r2.value);
  const lines = text.split('\n');

  assert.ok(text.includes('Voucher (SAVE10): €100.00'));
  const voucherIdx = lines.findIndex((l) => l.includes('Voucher'));
  const totalIdx = lines.findIndex((l) => l.startsWith('Total:'));
  assert.ok(voucherIdx < totalIdx);
});

test('renderInvoiceText shows due date when present', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 9, discountPercent: 0 }],
    terms: 'NET30',
  });

  const r2 = issueInvoice(r1.value, []);
  const text = renderInvoiceText(r2.value);

  assert.ok(text.includes('Due: 2026-11-06'));
});

test('renderInvoiceText does not show due date for draft', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 9, discountPercent: 0 }],
  });

  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');

  for (const line of lines) {
    assert.ok(!line.includes('Due:'));
  }
});

test('renderInvoiceText shows paid amount when there are payments', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 9, discountPercent: 0 }],
    terms: 'NET30',
  });

  const r2 = issueInvoice(r1.value, []);
  const r3 = recordPayment(r2.value, { amount: 50000, date: '2026-10-10' });
  const text = renderInvoiceText(r3.value);

  assert.ok(text.includes('Paid: €500.00'));
});

test('renderInvoiceText complete invoice with all features', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 9, discountPercent: 10 }],
    terms: 'NET30',
  });

  const r2 = applyVoucher(r1.value, { code: 'PROMO', amount: 5000 });
  const r3 = issueInvoice(r2.value, []);
  const r4 = recordPayment(r3.value, { amount: 30000, date: '2026-10-15' });
  const text = renderInvoiceText(r4.value);

  assert.ok(text.includes('INV-2026-0001'));
  assert.ok(text.includes('9 x Development (hour)'));
  assert.ok(text.includes('Discount: €95.00'));
  assert.ok(text.includes('Voucher (PROMO): €50.00'));
  assert.ok(text.includes('Due: 2026-11-06'));
  assert.ok(text.includes('Paid: €300.00'));
});

