test('renderInvoiceText shows voucher before total', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 9, discountPercent: 0 }],
  });

  const r2 = applyVoucher(r1.value, { code: 'SAVE10', amount: 10000 });
  const text = renderInvoiceText(r2.value);
  const lines = text.split('\n');

  assert.ok(text.includes('Voucher (SAVE10): €100.00'));
  const voucherIdx = lines.findIndex((l) => l.includes('Voucher'));
  const totalIdx = lines.findIndex((l) => l.startsWith('Total:'));
  assert.ok(voucherIdx < totalIdx);
});

test('renderInvoiceText shows due date when present', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 9, discountPercent: 0 }],
    terms: 'NET30',
  });

  const r2 = issueInvoice(r1.value, []);
  const text = renderInvoiceText(r2.value);

  assert.ok(text.includes('Due: 2026-11-06'));
});

test('renderInvoiceText does not show due date for draft', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 9, discountPercent: 0 }],
  });

  const text = renderInvoiceText(r.value);

  assert.ok(!text.includes('Due:'));
});

test('renderInvoiceText shows paid amount when there are payments', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 9, discountPercent: 0 }],
    terms: 'NET30',
  });

  const r2 = issueInvoice(r1.value, []);
  const r3 = recordPayment(r2.value, { amount: 50000, date: '2026-10-10' });
  const text = renderInvoiceText(r3.value);

  assert.ok(text.includes('Paid: €500.00'));
});

test('renderInvoiceText complete invoice with all features', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 9, discountPercent: 10 }],
    terms: 'NET30',
  });

  const r2 = applyVoucher(r1.value, { code: 'PROMO', amount: 5000 });
  const r3 = issueInvoice(r2.value, []);
  const r4 = recordPayment(r3.value, { amount: 30000, date: '2026-10-15' });
  const text = renderInvoiceText(r4.value);

  assert.ok(text.includes('INV-2026-0001'));
  assert.ok(text.includes('9 x Development (hour)'));
  assert.ok(text.includes('Discount: €85.50'));
  assert.ok(text.includes('Voucher (PROMO): €50.00'));
  assert.ok(text.includes('Due: 2026-11-06'));
  assert.ok(text.includes('Paid: €300.00'));
});

import { formatEuros } from './money.js';
import { getCustomer } from './customers.js';
import { lineTotal, lineDiscount, invoiceTotals } from './invoices.js';
import { balanceDue } from './payments.js';

/**
 * Render an invoice as plain text.
 * @param {{ number?: string, customerId: string, lines: Array<{ qty: number, name: string, unitPrice: number, discountPercent?: number }>, dueDate?: string, payments?: Array, voucher?: { code: string, amount: number } }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const numberLine = invoice.number || 'DRAFT';

  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : 'Unknown Customer';

  const lineItems = invoice.lines
    .map((line) => {
      const total = lineTotal(line);
      const discount = lineDiscount(line);
      let lineStr = `${line.qty} x ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(total)}`;
      if (discount > 0) {
        lineStr += `\n  Discount: ${formatEuros(discount)}`;
      }
      return lineStr;
    })
    .join('\n');

  const totals = invoiceTotals(invoice);
  const sections = [numberLine, customerName, lineItems];

  if (totals.voucher > 0) {
    const voucherCode = invoice.voucher?.code || 'VOUCHER';
    sections.push(`Voucher (${voucherCode}): ${formatEuros(totals.voucher)}`);
  }

  sections.push(`VAT: ${formatEuros(totals.vat)}`);
  sections.push(`Total: ${formatEuros(totals.total)}`);

  if (invoice.dueDate) {
    sections.push(`Due: ${invoice.dueDate}`);
  }

  if (invoice.payments && invoice.payments.length > 0) {
    const paid = invoice.payments.reduce((sum, p) => sum + p.amount, 0);
    sections.push(`Paid: ${formatEuros(paid)}`);
  }

  return sections.join('\n');
}

